		["Would you really like to deposit"] = "Você realmente quer depositar",
		["Yes? How can I {help} you?"] = "Sim? Como posso te {ajuda}?",
		["Yes? What may I do for you, |PLAYERNAME|? Bank business, perhaps?"] = "Sim? O que posso fazer por você, |PLAYERNAME|? Assunto de banco, talvez?",
		["You are hurt, my child. I will heal your wounds."] = "Você está ferido, meu filho. Vou curar suas feridas.",
		["You are poisoned. I will help you."] = "Você está envenenado. Vou te ajudar.",
		["You aren't looking really bad, |PLAYERNAME|. I can only help in cases of real emergencies. Raise your health simply by eating {food}."] = "Você não está tão mal assim, |PLAYERNAME|. Só posso ajudar em emergências de verdade. Recupere sua vida comendo {comida}.",
		["You aren't looking that bad. Sorry, I can't help you. But if you are looking for additional protection you should go on the {pilgrimage} of ashes or get the protection of the {twist of fate} here."] = "Você não está tão mal assim. Desculpe, não posso ajudar. Mas se procura proteção adicional, faça a {peregrinação} das cinzas ou receba a proteção da {reviravolta do destino} aqui.",
		["You can ask for the blessing of spiritual shielding in the whiteflower temple south of Thais."] = "Você pode pedir a bênção do escudo espiritual no templo da flor branca ao sul de Thais.",
		["You can ask for the blessing of the two suns in the suntower near Ab'Dendriel."] = "Você pode pedir a bênção dos dois sóis na torre do sol perto de Ab'Dendriel.",
		["You can buy and sell goods from merchants. To do so, simply talk to them and ask them for a {trade}. They will gladly show you their offers and also the things they buy from you."] = "Você pode comprar e vender com os comerciantes. Basta falar com eles e pedir para {negociar}. Eles mostram com prazer as ofertas e também o que compram de você.",
		["You can buy equipment from the {merchants} in this village once you earned some {gold}. Some {monsters} also carry equipment pieces with them."] = "Você pode comprar equipamento com os {comerciantes} do vilarejo assim que juntar algum {ouro}. Alguns {monstros} também carregam peças de equipamento.",
		["You can deposit your money at the bank. That way you won't lose it if you get {killed}. The bank is just under the academy and to the right."] = "Você pode depositar seu dinheiro no banco. Assim não o perde se {morrer}. O banco fica logo abaixo da academia, à direita.",
		["You can earn a fair amount of gold by fighting {monsters} and picking up the things they carry. Many {citizens} are buying some of that loot, simply ask around."] = "Dá para juntar bastante ouro combatendo {monstros} e recolhendo o que eles carregam. Muitos {moradores} compram esse loot; é só perguntar por aí.",
		["You can find the oracle on the top floor of the {academy}, just above {Seymour}. Go there when you are level 8 to find your {destiny}."] = "O oráculo fica no último andar da {academia}, logo acima do {Seymour}. Vá até lá ao chegar ao nível 8 para descobrir seu {destino}.",
		["You do not have enough capacity for all items."] = "Você não tem capacidade para todos os itens.",
		["You do not have enough gold."] = "Você não tem ouro suficiente.",
		["You do not have enough money to donate that amount."] = "Você não tem dinheiro suficiente para doar essa quantia.",
		["You do not have this object."] = "Você não tem esse objeto.",
		["You don't have enough money."] = "Você não tem dinheiro suficiente.",
		["You don't have it..."] = "Você não tem isso...",
		["You don't have so many."] = "Você não tem tantos assim.",
		["You have already started that mission."] = "Você já começou essa missão.",
		["You have done well. Here, take your reward."] = "Você se saiu bem. Tome, aqui está sua recompensa.",
		["You have not started that mission."] = "Você não começou essa missão.",
		["You must have passed the house of Lily on your way here. She sells {potions}. If you pick blueberries or find cookies, she'll buy them from you."] = "Você deve ter passado pela casa da Lily no caminho até aqui. Ela vende {potions}. Se colher amoras ou achar biscoitos, ela compra de você.",
		["You shouldn't miss the experience."] = "Você não devia perder essa experiência.",
		["Your near destiny will be to choose a {vocation} once you are level 8. Whether you will become a {knight}, {sorcerer}, {paladin} or {druid} is a big decision!"] = "Seu destino próximo é escolher uma {vocação} ao chegar ao nível 8. Se você será {knight}, {sorcerer}, {paladin} ou {druid} é uma grande decisão!",
		["|PLAYERNAME|, I am already talking to you."] = "|PLAYERNAME|, já estou falando com você.",
